        # has been round-tripped through our own database, so it is trusted here.
        sql = (
            f"SELECT * FROM {view['table_name']} "
            f"WHERE tenant_id = ? AND ({view['expression']}) "
            "LIMIT ?"
        )
        return self._conn.execute(sql, [tenant_id, int(limit)]).fetchall()

